package org.eclipse.rdf4j.query.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.junit.jupiter.api.Test;

class RemoteBNodeSpillAuthorityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void repeatedWrappersWithSameAuthorityReuseSpillReference() {
		Object epoch = new Object();
		var allocation = new BlankNodeAllocationScope("alias-", ignored -> false);
		BNode alias = (BNode) RemoteBNode.newResponseScope(allocation, VF, epoch, true)
				.map(VF.createBNode("canonical"));
		BNode copiedAlias = (BNode) RemoteBNode.preserveProvenance(alias, VF.createBNode(alias.getID()));
		assertThat(copiedAlias).isNotSameAs(alias);
		assertThat(copiedAlias.getID()).isEqualTo(alias.getID());

		try (var spill = new RemoteBNode.SpillScope()) {
			Object firstReference = spill.replace(alias);
			Object copiedReference = spill.replace(copiedAlias);

			assertThat(copiedReference).isEqualTo(firstReference);
			assertThat(RemoteBNode.toRemoteValue((Value) spill.resolve(firstReference), epoch, true, true))
					.isEqualTo(VF.createBNode("canonical"));
			assertThat(RemoteBNode.toRemoteValue((Value) spill.resolve(copiedReference), epoch, true, true))
					.isEqualTo(VF.createBNode("canonical"));
		}
	}

	@Test
	void equalAliasLabelsFromDifferentAuthoritiesCannotShareSpillReference() {
		Object firstEpoch = new Object();
		Object secondEpoch = new Object();
		var firstAllocation = new BlankNodeAllocationScope("alias-", ignored -> false);
		var secondAllocation = new BlankNodeAllocationScope("alias-", ignored -> false);
		BNode first = (BNode) RemoteBNode.newResponseScope(firstAllocation, VF, firstEpoch, true)
				.map(VF.createBNode("first-canonical"));
		BNode second = (BNode) RemoteBNode.newResponseScope(secondAllocation, VF, secondEpoch, true)
				.map(VF.createBNode("second-canonical"));
		assertThat(first.getID()).isEqualTo(second.getID());
		assertThat(((RemoteBNode) first).getProvenance()).isNotEqualTo(((RemoteBNode) second).getProvenance());

		try (var spill = new RemoteBNode.SpillScope()) {
			spill.replace(first);

			assertThatThrownBy(() -> spill.replace(second))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("blank-node identity");
		}
	}

	@Test
	void restoredNoncanonicalAliasReusesTheOuterSafeAlias() {
		Object foreignEpoch = new Object();
		var foreignAllocation = new BlankNodeAllocationScope("foreign-", ignored -> false);
		BNode foreign = (BNode) RemoteBNode.newResponseScope(foreignAllocation, VF, foreignEpoch, false)
				.map(VF.createBNode("canonical"));

		BNode restored;
		try (var spill = new RemoteBNode.SpillScope()) {
			Object reference = spill.replace(foreign);
			restored = (BNode) spill.resolve(reference);
		}
		assertThat(restored).isNotSameAs(foreign);
		assertThat(restored.getID()).isEqualTo(foreign.getID());
		assertThat(((RemoteBNode) restored).getProvenance()).isEqualTo(((RemoteBNode) foreign).getProvenance());

		Object outerEpoch = new Object();
		var outerAllocation = new BlankNodeAllocationScope("outer-", "outer-1"::equals);
		outerAllocation.reserve("outer-0"); // A reserved local identity must not become an imported alias.
		var outerResponse = RemoteBNode.newResponseScope(outerAllocation, VF, outerEpoch, false);
		Value mappedOriginal = outerResponse.map(foreign);
		Value mappedRestored = outerResponse.map(restored);

		assertThat(((BNode) mappedRestored).getID()).isEqualTo(((BNode) mappedOriginal).getID());
		assertThat(((RemoteBNode) mappedRestored).getProvenance())
				.isEqualTo(((RemoteBNode) mappedOriginal).getProvenance());
		assertThat(((BNode) mappedOriginal).getID()).isEqualTo("outer-2");
		assertThat(((RemoteBNode) mappedOriginal).getProvenance())
				.isEqualTo(new RemoteBNode.Provenance(foreignEpoch, "canonical", false));
		assertThatThrownBy(() -> RemoteBNode.toRemoteValue(mappedOriginal, foreignEpoch, true, true))
				.isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining("blank-node identity");
	}
}
